    // https://github.com/apple/swift-protobuf/issues/1182
    switch self.edit {
    case .insert?: try {
      guard case .insert(let v)? = self.edit else { preconditionFailure() }
      try visitor.visitSingularStringField(value: v, fieldNumber: 1)
