      guard case .deleteBackward(let v)? = self.edit else { preconditionFailure() }
      try visitor.visitSingularUInt32Field(value: v, fieldNumber: 2)
    }()
    case .imeEnter?: try {
      guard case .imeEnter(let v)? = self.edit else { preconditionFailure() }
      try visitor.visitSingularMessageField(value: v, fieldNumber: 3)
    }()
    case nil: break
    }
    try unknownFields.traverse(visitor: &visitor)
  }

  public static func ==(lhs: Tandem_V1_TextEdit, rhs: Tandem_V1_TextEdit) -> Bool {
    if lhs.edit != rhs.edit {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
